section.sourcecode:
file "ietf-foo@2016-03-20.yang"

    module ietf-foo {
      namespace "urn:ietf:params:xml:ns:yang:ietf-foo";
      prefix "foo";
      organization "...";
      contact "...";
      description "...";
      revision 2016-03-20 {
        description "Latest revision";
        reference "RFC FFFF: Foo Protocol";
      }
      // ... さらにステートメント
    }

module example-foo {
  namespace "tag:example.com,2017:example-foo";
  prefix f;

  container foo;
}

module example-bar {
  namespace "tag:example.com,2017:example-bar";
  prefix b;

  typedef foo { type uint32; }
}

module example-one {
  namespace "tag:example.com,2017:example-one";
  prefix one;
  import example-foo { prefix f; }
  import example-bar { prefix b; }

  augment "/f:foo" {
    leaf foo { type b:foo; }
  }
}

leaf type {
  type enumeration {
    enum a;
    enum b;
    enum c;
  }
  mandatory true;
}
choice type-choice {
  case b {
    container type-b {
      when "../type = 'b'";
      leaf foo {
        type string;
      }
    }
  }
  case c {
    container type-c {
      when "../type = 'c'";
      leaf bar {
        mandatory true;
        type string;
      }
    }
  }
}

leaf type {
  type enumeration {
    enum a;
    enum b;
    enum c;
  }
  mandatory true;
}
container type-b {
  when "../type = 'b'";
  leaf foo {
    type string;
  }
}
container type-c {
  when "../type = 'c'";
  leaf bar {
    mandatory true;
    type string;
  }
}

leaf type {
  type enumeration {
    enum a;
    enum b;
    enum c;
  }
}
choice second-type {
  mandatory true;
  case foo {
    container foo {
      presence "When present, indicates type foo";
      leaf foo-attribute {
        type string;
      }
    }
  }
  case b {
    container bar {
      when "../type = 'a' or ../type = 'b'";
      presence "When present, indicates type bar";
      leaf bar-attribute {
        type string;
      }
    }
  }
  case c {
    container baz {
      when "../type = 'c'";
      leaf baz-attribute {
        mandatory true;
        type string;
      }
    }
  }
}

notification foo {
  leaf mtu {
    // when-stmt のコンテキストがこの通知なので NG
    when "/if:interfaces/if:interface[name='eth0']";
    type leafref {
      // path-stmt のコンテキストが異なるので OK
      path "/if:interfaces/if:interface/if:mtu";
    }
  }
}

// "ex" は、アイデンティティー name-format-null が
// 定義されているモジュールの接頭辞とする

// 使用しない
when "md-name-format = 'name-format-null'";

// こちらが好ましい
when "derived-from-or-self(md-name-format, 'ex:name-format-null')";

augment "/rt:active-route/rt:input/rt:destination-address" {
  when "derived-from-or-self(rt:address-family, "
     + "'v4ur:ipv4-unicast')" {
    description
      "This augment is valid only for IPv4 unicast.";
  }
  // ここで augment-stmt 内に定義されたノードは
  // when-stmt で参照できない
}

when /foo/services/*/active {
  description
    "No services directly defined in this module.
     Matches objects that have augmented the services container.";
}

leaf foo1 {
  type enumeration {
    enum one;
    enum two;
    enum three;
  }
}

leaf foo2 {
  // 誤り
  must "/f:foo1 != 'two'";
  type string;
}
leaf foo2 {
  // 正しい
  must "/f:foo1 = 'one' or /f:foo1 = 'three'";
  type string;
}

leaf foo1 {
  type enumeration {
    enum one;
    enum two;
    enum three;
    enum four;
  }
}

import ietf-yang-types {
   prefix yang;
   reference "RFC 9911: Common YANG Data Types";
}

leaf reserved {
  type string;
  description
    "This object has no purpose at this time, but a future
     revision of this module might define a purpose
     for this object.";
}

revision 2010-09-24 {
  description
    "Initial revision.";
reference
  "RFC 6021: Common YANG Data Types";
}

revision 2013-07-15 {
  description
    "This revision adds the following new data types:
     - yang:yang-identifier
     - yang:hex-string
     - yang:uuid
     - yang:dotted-quad";
   reference
     "RFC 6991: Common YANG Data Types";
 }

 revision 2010-09-24 {
   description
     "Initial revision.";
 reference
   "RFC 6021: Common YANG Data Types";
 }

revision 2025-12-22 { description "This revision adds the following new data types: - yang:date - yang:date-no-zone - yang:time - yang:time-no-zone - yang:hours32 - yang:minutes32 - yang:seconds32 - yang:centiseconds32 - yang:milliseconds32 - yang:microseconds32 - yang:microseconds64 - yang:nanoseconds32 - yang:nanoseconds64 - yang:language-tag The yang-identifier definition has been aligned with YANG 1.1 and types representing time support the representation of leap seconds. The representation of time zone offsets has been aligned with RFC 9557. Several description and pattern statements have been improved."; reference "RFC 9911: Common YANG Data Types"; }
revision 2013-07-15 { description "This revision adds the following new data types: - yang:yang-identifier - yang:hex-string - yang:uuid - yang:dotted-quad"; reference "RFC 6991: Common YANG Data Types"; }
revision 2010-09-24 { description "Initial revision."; reference "RFC 6021: Common YANG Data Types"; }

leaf foo {
  type enumeration {
    enum one;
    enum two;
  }
}

identity foo-type {
  description "Base for the extensible type";
}

identity one {
  base f:foo-type;
}

identity two {
  base f:foo-type;
}

leaf foo {
  type identityref {
    base f:foo-type;
  }
}

typedef ipv6-address-no-zone {
  type inet:ipv6-address {
    pattern '[0-9a-fA-F:\.]*';
  }
  ...
}

typedef yang-identifier {
  type string {
    length "1..max";
    pattern '[a-zA-Z_][a-zA-Z0-9\-_.]*';
    pattern '.|..|[^xX].*|.[^mM].*|..[^lL].*';
  }
  ...
}

typedef dscp {
  type uint8 {
    range "0..63";
  }
  ...
}

leaf foo {
  // 誤り
  type enumeration {
    enum one;
    enum two;
  }
  description
    "The foo enum...
     one: The first enum
     two: The second enum";
}
leaf foo {
  // 正しい
  type enumeration {
    enum one {
      description "The first enum";
    }
    enum two {
      description "The second enum";
    }
  }
  description
    "The foo enum...  ";
}

type union {
  type string;
  type enumeration {
    enum up;
    enum down;
  }
}

type union {
  type enumeration {
    enum up;
    enum down;
  }
  type string;
}

type union {
  type string;
  type int32;
}

type union {
  type int32;
  type string;
}

leaf flag1 {
  type empty;
}

leaf flag2 {
  type boolean;
  default false;
}

container top {
   container foos {
      list foo { ... }
   }
   container bars {
      list bar { ... }
   }
}

container top {
   list foo { ... }
   list bar { ... }
}

notification interface-up {
  description "Sent when an interface is activated.";
  leaf name {
    type leafref {
      path "/if:interfaces/if:interface/if:name";
    }
  }
}

feature feature1 {
  description "Some protocol feature";
}

feature feature2 {
  if-feature "feature1";
  description "Another protocol feature";
}

augment "/if:interfaces/if:interface" {
    when "if:type = 'ianaift:ethernetCsmacd'";

    container ethernet {
        leaf duplex {
            ...
        }
    }
}

module example-module {

  yang-version 1.1;
  namespace "tag:example.com,2017:example-module";
  prefix mymod;

  import iana-if-type { prefix iana; }
  import ietf-interfaces { prefix if; }

  identity some-new-iftype {
    base iana:iana-interface-type;
  }

  augment "/if:interfaces/if:interface" {
    when "if:type = 'mymod:some-new-iftype'";

    leaf mandatory-leaf {
      type string;
      mandatory true;
    }
  }
}

container backups {
  list backup {
    ...
    max-elements 10;
    ...
  }
}

deviation /bk:backups/bk:backup {
  deviate add {
    max-elements 10;
  }
}

list foo {
   key name;
   leaf name {
      type string;
   }
   ...
}

list foo-addon {
   key name;
   config false;
   leaf name {
      type string;
   }
   ...
}

list foo {
   key name;
   leaf name {
      type string;
   }
   ...
}

list foo-addon {
   key name;
   config false;
   leaf name {
      type leafref {
         path "/foo/name";
         require-instance false;
      }
   }
   leaf addon {
      type string;
      mandatory true;
   }
}

container foo {
  ...
  // 対応する "config true" のオブジェクトを持たない
  // "config true" と "config false" のノード（例: カウンター）を含む
}

 module example-foo {
   namespace "urn:example:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 構成データの子ノード
     // 運用状態データストアにのみある運用上の値
     // 必要に応じて "config false" ノードを含められる
   }
}

 module example-foo {
   namespace "urn:example:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 構成データの子ノード
   }

   container foo-state {
     config false;
     // 運用状態の子ノード
   }
}

 module example-foo {
   namespace "urn:example:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 構成データの子ノード
     // 運用状態データストアにのみある運用上の値
     // 必要に応じて "config false" ノードを含められる
     // 古い foo-state のデータノードをすべて含む
   }

   // 元の foo-state を残すが、ステータスを deprecated に変更する
   container foo-state {
     config false;
     status deprecated;
     // 運用状態の子ノード
   }
}

module example-foo-state {
  namespace "urn:example:params:xml:ns:yang:example-foo-state";
  prefix "foo-s";

  // 新しいモジュールまたは変換されたモジュールをインポートする。この例では未使用
  import example-foo { prefix foo; }

  container foo-state {
    config false;
    status deprecated;
    // 運用状態の子ノード
   }
}

rpc reset {
  input {
    leaf interface {
      type if:interface-ref;
      mandatory true;
      description "The interface to reset.";
    }
  }
}

container interfaces {
  list interface {
    ...
    action reset { }
  }
}

module example-module {
  namespace "https://example.com/yang/example";
  prefix "ex";
  //...
  import module-tags { prefix tags; }

  tags:module-tag "ietf:some-new-tag";
  tags:module-tag "ietf:some-other-tag";
  // ...
}

revision 2023-11-27 {
  description
    "Registered RR Type RESINFO 261.";
  reference
    "https://www.iana.org/assignments/yang-parameters/"
  + "iana-dns-class-rr-type@2023-11-27.yang";
}

revision 2023-11-08 {
  description
    "Updated description and replaced draft string reference to
     64 and 65 with RFC 9460: Service Binding and Parameter
     Specification via the DNS (SVCB and HTTPS Resource Records).";
  reference
    "RFC 9460: Service Binding and Parameter Specification via the
               DNS (SVCB and HTTPS Resource Records)
     https://www.iana.org/assignments/yang-parameters/"
  + "iana-dns-class-rr-type@2023-11-08.yang";
}

revision 2023-04-25 {
  description
    "Updated reference for 64 and 65.";
  reference
    "https://www.iana.org/assignments/yang-parameters/"
  + "iana-dns-class-rr-type@2023-04-25.yang";
}

revision 2022-05-30 {
  description
    "Updated description, reference for 64 and 65.";
  reference
    "https://www.iana.org/assignments/yang-parameters/"
  + "iana-dns-class-rr-type@2022-05-30.yang";
}

revision 2021-08-31 {
  description
    "Initial revision.";
  reference
    "RFC 9108: YANG Types for DNS Classes and Resource Record
               Types";
}

revision 2021-04-23 {
  description
    "Registered tunnelType 19.";
  reference
    "RFC 4301: Security Architecture for the Internet Protocol";
}

revision 2019-11-16 {
  description
    "Initial revision.";
  reference
    "RFC 8675: A YANG Data Model for Tunnel Interface Types";
}

...

